/** 青训特质英文名（数据层）：与 game/prospects.ts 的 TRAITS 对应，渲染期 pick(中文, 英文)。 */
export const PROSPECT_TRAIT_NAME_EN: Record<string, string> = {
  可塑性强: 'Coachable',
  枪法生猛: 'Guns blazing',
  大器晚成: 'Late bloomer',
  稳定输出: 'Consistent output',
  脾气火爆: 'Hot-headed',
  沉默领袖: 'Silent leader',
  道具狂人: 'Utility nut',
  残局猎手: 'Clutch hunter',
};

/** 天赋技能英文名：技能条目自带 nameEn；青训选手的技能名取自特质，回退到特质表。 */
export function skillNameEn(skill: Skill): string {
  const own = Object.values(SKILLS).find((s) => s.id === skill.id);
  return own ? own.nameEn : (PROSPECT_TRAIT_NAME_EN[skill.name] ?? skill.name);
}

const RARITY_SKILL_POOL: Record<Rarity, string[]> = {
  N: ['serverRat', 'mirager', 'infernist'],
  R: ['duelist', 'tradeArtist', 'mirager', 'infernist', 'nuker'],
  SR: ['duelist', 'utilityLib', 'tradeArtist', 'clutchGene', 'architect', 'nuker', 'glue'],
  SSR: ['duelist', 'utilityLib', 'clutchGene', 'architect', 'iceVeins', 'sponsor', 'glue'],
  UR: ['iceVeins', 'architect', 'duelist', 'utilityLib', 'clutchGene'],
};

function toAttributes(a: number[]): Attributes {
  return { aim: a[0], reflex: a[1], positioning: a[2], gameSense: a[3], utility: a[4], teamwork: a[5], clutch: a[6], leadership: a[7] };
}
function toProf(p: number[]): RoleProf {
  return { AWPer: p[0], Entry: p[1], Lurker: p[2], Support: p[3], Anchor: p[4], IGL: p[5] };
}
function toMaps(m: number[]): MapProf {
  const order: MapId[] = MAP_IDS;
  return order.reduce((acc, id, i) => { acc[id] = m[i]; return acc; }, {} as MapProf);
}

function tpl(
  playerId: string, season: string, rarity: Rarity, primaryRole: Role, secondaryRole: Role,
  attr: number[], prof: number[], maps: number[], skillId: string, growth = 1,
): CardTemplate {
  return {
    id: `tpl-${playerId}-${season}`,
    playerId, season, rarity, primaryRole, secondaryRole,
    attributes: toAttributes(attr),
    proficiency: toProf(prof),
    mapProficiency: toMaps(maps),
    skill: SKILLS[skillId],
    growth,
  };
}

