export const TEMPLATE_MAP: Record<string, CardTemplate> = Object.fromEntries(CARD_TEMPLATES.map((t) => [t.id, t]));

export const TEMPLATES_BY_RARITY: Record<Rarity, CardTemplate[]> = {
  N: CARD_TEMPLATES.filter((t) => t.rarity === 'N'),
  R: CARD_TEMPLATES.filter((t) => t.rarity === 'R'),
  SR: CARD_TEMPLATES.filter((t) => t.rarity === 'SR'),
  SSR: CARD_TEMPLATES.filter((t) => t.rarity === 'SSR'),
  UR: CARD_TEMPLATES.filter((t) => t.rarity === 'UR'),
};

export function getTemplate(id: string): CardTemplate | undefined {
  return TEMPLATE_MAP[id];
}

export function skillFor(rarity: Rarity, seedIndex: number): Skill {
  const pool = RARITY_SKILL_POOL[rarity];
  return SKILLS[pool[seedIndex % pool.length]];
}

export function attributeLabel(key: keyof Attributes): string {
  return key;
}

/** 初始五张卡：一名可靠主狙 + 四名新人，保证开局能打第一场。 */
export function starterTemplateIds(): string[] {
  return ['tpl-torzsi-2026', 'tpl-dupreeh-2026', 'tpl-senzu-2026', 'tpl-techno-2026', 'tpl-siuhy-2026'];
}

export function defaultSquadRoles(): Record<CombatRole, string> {
  return {
    AWPer: 'tpl-torzsi-2026',
    Entry: 'tpl-dupreeh-2026',
    Lurker: 'tpl-senzu-2026',
    Support: 'tpl-techno-2026',
    Anchor: 'tpl-siuhy-2026',
  };
}

export function playerBio(playerId: string): string | undefined {
  return PLAYER_MAP[playerId]?.bio;
}

/** 已退役选手的最后一个正式赛季年份。 */
export function playerRetired(playerId: string): number | undefined {
  return PLAYER_MAP[playerId]?.retired;
}